class ConstraintViolations {
    private final List<String> messages = new java.util.ArrayList<>();

    public void add(String message) {
        messages.add(message);
    }

    public boolean isValid() {
        return messages.isEmpty();
    }

    public int size() {
        return messages.size();
    }

    public List<String> getMessages() {
        return messages;
    }
}

class Validator<T> implements Validatable<T> {
    private final List<ConstraintPredicate<T, ?>> predicatesList;
    private final boolean failFast;

    public Validator(List<ConstraintPredicate<T, ?>> predicatesList, boolean failFast) {
        this.predicatesList = predicatesList;
        this.failFast = failFast;
    }

    @Override
    public ConstraintViolations validate(T target, Locale locale, ConstraintContext constraintContext) {
        ConstraintViolations violations = new ConstraintViolations();
        for (ConstraintPredicate<T, ?> predicate : predicatesList) {
            if (!predicate.test(target)) {
                violations.add(predicate.getMessage());
                if (failFast) {
                    break;
                }
            }
        }
        return violations;
    }
}

interface ConstraintPredicate<T, R> {
    boolean test(T t);
    String getMessage();
}

class NamePredicate implements ConstraintPredicate<User, String> {
    @Override
    public boolean test(User user) {
        return user.getName() != null && !user.getName().isEmpty();
    }

    @Override
    public String getMessage() {
        return "The name must not be empty.";
    }
}

class EmailPredicate implements ConstraintPredicate<User, String> {
    @Override
    public boolean test(User user) {
        return user.getEmail() != null && user.getEmail().contains("@");
    }

    @Override
    public String getMessage() {
        return "The email format is invalid.";
    }
}

class AgePredicate implements ConstraintPredicate<User, Integer> {
    @Override
    public boolean test(User user) {
        return user.getAge() <= 120;
    }

    @Override
    public String getMessage() {
        return "The age exceeds the maximum allowed value.";
    }
}

class EnabledPredicate implements ConstraintPredicate<User, Boolean> {
    @Override
    public boolean test(User user) {
        return user.isEnabled();
    }

    @Override
    public String getMessage() {
        return "The account must be enabled.";
    }
}

class User {
    private final String name;
    private final String email;
    private final int age;
    private final boolean enabled;

    public User(String name, String email, int age, boolean enabled) {
        this.name = name;
        this.email = email;
        this.age = age;
        this.enabled = enabled;
    }

    public String getName() { return name; }
    public String getEmail() { return email; }
    public int getAge() { return age; }
    public boolean isEnabled() { return enabled; }
}

class ValidatorTest {

    @Test
    void validateUserWithMultipleInvalidFields() {
        // Arrange
        User user = new User("", "invalid-email", 150, false);
        Validator<User> validator = createValidator();
        Locale locale = Locale.getDefault();
        ConstraintContext context = new ConstraintContext() {
            @Override
            public String name() {
                return "testContext";
            }
            // Implement other necessary methods if required
        };

        // Act
        ConstraintViolations violations = validator.validate(user, locale, context);

        // Assert
        assertThat(violations.isValid()).isFalse();
        assertThat(violations.size()).isEqualTo(4);
        assertThat(violations.getMessages()).containsExactlyInAnyOrder(
            "The name must not be empty.",
            "The email format is invalid.",
            "The age exceeds the maximum allowed value.",
            "The account must be enabled."
        );
    }

    private Validator<User> createValidator() {
        return new Validator<>(
            List.of(
                new NamePredicate(),
                new EmailPredicate(),
                new AgePredicate(),
                new EnabledPredicate()
            ),
            false
        );
    }
}

