class ValidatorTest {

    @Test
    void validateEmailFieldErrors() {
        User user = new User("foo", "aa", 200, true);
        Validator<User> validator = validator();
        ConstraintViolations violations = validator.validate(user, Locale.ENGLISH, new ConstraintContext());

        assertThat(violations.isValid()).isFalse();

        List<ViolationDetail> details = violations.details();
        assertThat(details.size()).isEqualTo(2);

        ViolationDetail sizeViolation = details.get(0);
        assertThat(sizeViolation.getDefaultMessage()).isEqualTo("The size of \"email\" must be greater than or equal to 5. The given size is 2");
        assertThat(sizeViolation.getKey()).isEqualTo("container.greaterThanOrEqual");

        ViolationDetail formatViolation = details.get(1);
        assertThat(formatViolation.getDefaultMessage()).isEqualTo("\"email\" must be a valid email address");
        assertThat(formatViolation.getKey()).isEqualTo("charSequence.email");
    }

    private Validator<User> validator() {
        return new Validator<User>() {
            @Override
            public ConstraintViolations validate(User target, Locale locale, ConstraintContext context) {
                ConstraintViolations violations = new ConstraintViolations();

                // Validate email size
                if (target.getEmail() == null || target.getEmail().length() < 5) {
                    violations.add(new ViolationDetail(
                            "container.greaterThanOrEqual",
                            "The size of \"email\" must be greater than or equal to 5. The given size is " + (target.getEmail() == null ? 0 : target.getEmail().length())
                    ));
                }

                // Validate email format (simple check for '@' character)
                if (target.getEmail() != null && !target.getEmail().contains("@")) {
                    violations.add(new ViolationDetail(
                            "charSequence.email",
                            "\"email\" must be a valid email address"
                    ));
                }

                return violations;
            }
        };
    }
