        ConstraintPredicates<User, String> namePredicates = new ConstraintPredicates<>(
                User::getName,
                "name",
                Arrays.asList(nameConstraint)
        );

        // Conditional validator for UPDATE group
        Pair<ConstraintCondition<User>, Validatable<User>> conditionalValidator = new Pair<>(
                (u, ctx) -> true, // Always true for testing
                new Validator<>(
