		CalendarEntryLocalDateTime birthdayPartyEntry = new CalendarEntryLocalDateTime(
				"BirthdayParty", now);

		Validator<CalendarEntryLocalDateTime> validator = ValidatorBuilder
				.<CalendarEntryLocalDateTime> of()
