import org.junit.jupiter.api.Test;

import static org.assertj.core.api.Assertions.assertThat;

class YearConstraintTest {

    @Test
    void isAtLeastTenYearsAhead() {
        // Fixed current year for testing
        Clock fixedClock = Clock.fixed(Instant.parse("2023-01-01T00:00:00Z"), ZoneId.systemDefault());
        Year currentYear = Year.now(fixedClock);
        int yearsAhead = 10;

        // Set up the constraint to check if a year is at least 10 years ahead
        YearConstraint<Year> constraint = new YearConstraint<>();
        Predicate<Year> predicate = year -> constraint.isAfter(currentYear, year);

        // Test with the current year (should return false)
        assertThat(predicate.test(currentYear)).isFalse();

        // Test with a year exactly 10 years ahead (should return true)
        Year futureYear = currentYear.plusYears(yearsAhead);
        assertThat(predicate.test(futureYear)).isTrue();
    }
}

