				CHAR_SEQUENCE_PATTERN, () -> new Object[] { regex.pattern() }, VALID));
		return this;
	}

	/**
	 * @since 0.11.1
	 */
	public CharSequenceConstraint<T, E> pattern(Supplier<Pattern> regexSupplier) {
