<COVER>			VariantOptions variantOptions) {
<COVER>		this.normalizerForm = normalizerForm;
<COVER>		this.variantOptions = variantOptions;
	}

	public ByteSizeConstraint<T, E> asByteArray(Charset charset) {
		return new ByteSizeConstraint<>(this, charset);
