	/**
	 * @since 0.6.0
	 */
	public CharSequenceConstraint<T, E> isDouble() {
<COVER>		return this.isValidRepresentationOf(Double::parseDouble, CHAR_SEQUENCE_DOUBLE);
	}

	/**
	 * @since 0.6.0
	 */
	public CharSequenceConstraint<T, E> isBigInteger() {
