			Function<VariantOptions.Builder, VariantOptions.Builder> opts) {
		VariantOptions.Builder builder = VariantOptions.builder();
		CharSequenceConstraint<T, E> constraint = new CharSequenceConstraint<>(
				this.normalizerForm, opts.apply(builder).build());
		constraint.predicates().addAll(this.predicates());
		return constraint;
	}

	protected String normalize(String s) {
<COVER>		String str = this.variantOptions.ignored(s);
<COVER>		return this.normalizerForm == null ? str
<COVER>				: Normalizer.normalize(str, this.normalizerForm);
	}

	@Override
	protected ToIntFunction<E> size() {
<COVER>		return cs -> {
<COVER>			String s = this.normalize(cs.toString());
<COVER>			return s.codePointCount(0, s.length());
		};
	}

	private static String trim(String s) {
		if (s.length() == 0) {
			return s;
		}
		StringBuilder sb = new StringBuilder(s);
		while (sb.length() > 0 && Character.isWhitespace(sb.charAt(0))) {
			sb.deleteCharAt(0);
		}
		while (sb.length() > 0 && Character.isWhitespace(sb.charAt(sb.length() - 1))) {
			sb.deleteCharAt(sb.length() - 1);
		}
		return sb.toString();
	}
}

