				DateTimeFormatter.ofPattern(pattern)
						.withResolverStyle(ResolverStyle.STRICT).parse(x);
				return true;
			}
			catch (DateTimeParseException ignored) {
				return false;
			}
		}, CHAR_SEQUENCE_LOCAL_DATE, () -> new Object[] { pattern }, VALID));
		return this;
