	 * @since 0.7.0
	 */
	public CharSequenceConstraint<T, E> ipv4() {
		this.predicates()
				.add(ConstraintPredicate.of(x -> InetAddressUtils.isIpv4(x.toString()),
						CHAR_SEQUENCE_IPV4, () -> new Object[] {}, VALID));
		return this;
	}

