		this.predicates()
				.add(ConstraintPredicate.of(x -> regexSupplier.get().matcher(x).matches(),
						CHAR_SEQUENCE_PATTERN,
						() -> new Object[] { regexSupplier.get().pattern() }, VALID));
		return this;
	}

