package am.ik.yavi.constraint;

import java.time.Instant;
import java.util.function.Predicate;

import org.junit.jupiter.api.Test;

import static org.assertj.core.api.Assertions.assertThat;

class InstantConstraintTest {

    @Test
    void afterOrEqualConstraintReturnsTrueForEqualInstants() {
        Instant now = Instant.now();
        InstantConstraint<Instant> constraint = new InstantConstraint<>();
        Predicate<Instant> predicate = constraint.afterOrEqual(() -> now).predicates().peekFirst().predicate();
        assertThat(predicate.test(now)).isTrue();
    }
}

