package am.ik.yavi.constraint;

import java.time.Clock;
import java.time.Instant;
import java.time.LocalTime;
import java.time.ZoneId;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

class LocalTimeConstraintTest {

    @Test
    void isBefore_ShouldReturnFalseForCurrentTimeAndTrueForPastTime() {
        Clock fixedClock = Clock.fixed(Instant.now(), ZoneId.systemDefault());
        LocalTime now = LocalTime.now(fixedClock);
        LocalTime pastTime = now.minusMinutes(1);

        LocalTimeConstraint<LocalTime> constraint = new LocalTimeConstraint<>();

        // Test with current time
        boolean resultCurrent = constraint.isBefore(now, now);
        assertFalse(resultCurrent, "Current time should not be considered before itself.");

        // Test with past time
        boolean resultPast = constraint.isBefore(pastTime, now);
        assertTrue(resultPast, "Past time should be considered before the current time.");
    }
}

