import java.util.stream.Collectors;

import org.junit.jupiter.api.Test;

import static org.assertj.core.api.Assertions.assertThat;

class CodePointsConstraintTest {

    interface ConstraintPredicate<T> {
        Optional<ViolatedValue> violatedValue(T value);
    }

    static class ViolatedValue {
        private final List<String> value;

        public ViolatedValue(List<String> value) {
            this.value = value;
        }

        public List<String> getValue() {
            return value;
        }
    }

    @Test
    void blackListConstraint() {
        Set<Integer> blackList = new HashSet<>(
            Arrays.asList(0x0041 /* A */, 0x0042 /* B */, 0x0061 /* a */, 0x0062 /* b */));

        ConstraintPredicate<String> predicate = value -> {
            Set<Integer> excludedFromBlackList = blackList;
            Set<Integer> blocked = new HashSet<>();
            String str = value;
            int len = str.length();
            for (int i = 0; i < len; ) {
                int codePoint = str.codePointAt(i);
                if (excludedFromBlackList.contains(codePoint)) {
                    blocked.add(codePoint);
                }
                i += Character.charCount(codePoint);
            }
            if (blocked.isEmpty()) {
                return Optional.empty();
            }
            List<String> blockedList = blocked.stream()
                    .map(i -> new String(new int[] { i }, 0, 1))
                    .collect(Collectors.toList());
            return Optional.of(new ViolatedValue(blockedList));
        };

        // Strings without blocked characters
        assertThat(predicate.violatedValue("CD").isPresent()).isFalse();
        assertThat(predicate.violatedValue("cd").isPresent()).isFalse();

        // Strings with blocked characters
        Optional<ViolatedValue> violatedABCD = predicate.violatedValue("ABCD");
        assertThat(violatedABCD.isPresent()).isTrue();
        assertThat(violatedABCD.get().getValue())
                .isEqualTo(Arrays.asList("A", "B"));

        Optional<ViolatedValue> violatedAbCD = predicate.violatedValue("AbCD");
        assertThat(violatedAbCD.isPresent()).isTrue();
        assertThat(violatedAbCD.get().getValue())
                .isEqualTo(Arrays.asList("A", "b"));
    }
}

