package am.ik.yavi.fn;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import java.util.Arrays;
import java.util.List;
import java.util.NoSuchElementException;
import java.util.stream.Collectors;
import am.ik.yavi.fn.Validation;

public class ValidationTest {

    @Test
    void testFailure() {
        List<String> errors = Arrays.asList("Error1", "Error2");
        Validation<String, Integer> validation = Validation.failure(errors);

        // Ensure the validation instance is marked as invalid
        assertFalse(validation.isValid());

        // Accessing the value should throw NoSuchElementException
        assertThrows(NoSuchElementException.class, validation::value);

        // The errors list contains the specified error messages
        assertEquals(errors, validation.errors());

        // The map method retains the original errors
        Validation<String, Integer> mapped = validation.map(v -> v + 1);
        assertFalse(mapped.isValid());
        assertEquals(errors, mapped.errors());

        // The mapErrors method correctly transforms the error messages
        Validation<String, Integer> mappedErrors = validation.mapErrors(errs -> 
            errs.stream().map(e -> e + " transformed").collect(Collectors.toList())
        );
        assertFalse(mappedErrors.isValid());
        List<String> expectedTransformed = Arrays.asList("Error1 transformed", "Error2 transformed");
        assertEquals(expectedTransformed, mappedErrors.errors());

        // The flatMap method retains the original errors
        Validation<String, Integer> flatMapped = validation.flatMap(v -> Validation.success(v + 1));
        assertFalse(flatMapped.isValid());
        assertEquals(errors, flatMapped.errors());

        // The validation instance equals another instance with the same errors
        Validation<String, Integer> sameValidation = Validation.failure(errors);
        assertEquals(validation, sameValidation);

        // The hash code of the validation instance matches another instance with the same errors
        assertEquals(validation.hashCode(), sameValidation.hashCode());
    }
}

