package am.ik.yavi.fn;

import java.util.Arrays;
import java.util.List;

import org.junit.jupiter.api.Test;

import static org.assertj.core.api.Assertions.assertThat;

class ValidationsTest {

    @Test
    void sequenceCollectsAllErrorMessages() {
        List<Validation<List<String>, Integer>> validations = Arrays.asList(
            Validation.<List<String>, Integer>success(1),
            Validation.<List<String>, Integer>failure(Arrays.asList("e1", "e2")),
            Validation.<List<String>, Integer>success(2),
            Validation.<List<String>, Integer>failure(Arrays.asList("e3", "e4"))
        );
        Validation<List<String>, List<Integer>> result = Validations.sequence(validations);
        assertThat(result.isValid()).isFalse();
        assertThat(result.errors()).containsExactlyElementsOf(Arrays.asList("e1", "e2", "e3", "e4"));
    }

}

