	@Test
	void traverseInvalid() {
		final Validation<String, List<Integer>> validation = Validations
				.traverse(Arrays.asList(1, -1, 2, -2), i -> {
					if (i > 0) {
						return Validation.success(i);
					}
					else {
						return Validation.failure(
								Arrays.asList("e" + (-2 * i - 1), "e" + (-2 * i)));
					}
				});
